function roadEndpoint(x,y){for(let r=1;r<=3;r++)for(let dy=-r;dy<=r;dy++)for(let dx=-r;dx<=r;dx++)if(Math.abs(dx)+Math.abs(dy)===r){let xx=x+dx,yy=y+dy;if(xx>=0&&yy>=0&&xx<W&&yy<H&&state.grid[yy][xx].road)return[xx,yy]}return null}
