 if(selected){let c=state.grid[selected.y][selected.x];el('coord').textContent='CELL '+(selected.x+1)+','+(selected.y+1);let title=c.building?defs[c.building].icon+' '+defs[c.building].name:c.road?'🛣️ 도로':c.zone?'📍 '+defs[c.zone].name:c.terrain==='water'?'🌊 바다 타일':c.terrain==='shore'?'🏖️ 해안':'🌿 자연 지형';let note=c.building?defs[c.building].desc:c.zone?'도로 인접 '+(roadNear(selected.x,selected.y)?'· 연결됨':'· 도로 필요')+' / '+(c.building?'레벨 '+c.level:'건물 대기 중'):c.road?'거제 도시 도로망에 연결되어 있습니다.':'도로 옆 타일에 구역을 지정할 수 있어요.';if(c.building&&c.zone==='res')note+=' · '+c.level+'랭크 · 집값 '+homeValue(selected.x,selected.y,c).toLocaleString()+'원 · 오염 '+pollutionAt(selected.x,selected.y);el('selectedInfo').innerHTML='<h3>'+title+'</h3><p>'+note+'</p>'}else el('coord').textContent=W+' × '+H+' 픽셀 지도';
