function placeAt(x,y){if(!landCell(x,y))return toast('바다에는 건설할 수 없어요.');let c=state.grid[y][x];if(active==='inspect'){selected={x,y};renderUI();rebuildCity();return}if(active==='bulldoze'){if(!c.road&&!c.zone&&!c.building)return;let t=c.building||c.zone||'road';if(defs[t])state.money+=Math.floor(defs[t].cost*.25);c.road=false;c.zone=null;c.building=null;c.level=0;selected={x,y};addLog('선택한 도로와 시설을 철거했어요.');renderUI();rebuildCity();return}if(c.road||c.zone||c.building)return toast('이미 도로나 시설이 있는 자리예요.');if(!roadNear(x,y))return toast('도로와 맞닿은 땅을 선택하세요.');let d=defs[active];if(!d)return;if(state.money<d.cost)return toast('도시 자금이 부족해요.');state.money-=d.cost;if(active==='road')c.road=true;else if(['res','com','ind','fish','farm'].includes(active))c.zone=active;else c.building=active;selected={x,y};addLog(d.name+'을 설치했어요.');renderUI();rebuildCity();toast(d.name+' 설치 완료');beep(620)}
