function beep(f){if(!sound)return;try{audio=audio||new AudioContext();let o=audio.createOscillator(),g=audio.createGain();o.connect(g);g.connect(audio.destination);o.frequency.value=f;g.gain.setValueAtTime(.03,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.12);o.start();o.stop(audio.currentTime+.12)}catch(e){}}
const guideSteps=[['시장님, 거제에 오신 걸 환영해요!','저는 도시 안내원 리센느예요. 픽셀 지도를 둘러보며 도시를 함께 키워 봐요.'],['먼저 도로를 연결해요','왼쪽 도로 도구를 고른 뒤 빈 땅을 누르세요. 구역과 건물은 도로 옆에 지을 수 있어요.'],['수도와 전기를 공급해요','급수 시설과 풍력 발전소가 주거·상업·산업 건물에 닿아야 건물이 운영돼요. 현재 장승포 중심지는 기본 시설이 연결되어 있어요.'],['도시 구역을 나눠요','주거 구역에 집이 생겨요. 상업 구역은 물건을 팔고, 공업·어업·농업 구역은 각각 공산품·수산물·농산물을 만듭니다.'],['주민과 화물은 도로로 이동해요','공장과 농장, 어장에서 상가로 화물차가 오가고 주민과 일꾼도 도로를 이용해요. 물품 공급이 부족하면 상가 수입이 줄어요.'],['행복과 집값을 살펴요','숲과 해안, 공원은 행복을 높여요. 상가는 집값을 올리지만 공장은 주변을 오염시켜 집값과 행복을 낮춰요. 집값과 행복이 충분하면 주택이 리모델링되어 세수가 늘어요.'],['공공시설과 편의시설을 챙겨요','경찰서·소방서·보건소·학교가 주민 가까이 있어야 해요. 부족하면 범죄·화재·역병이 생길 수 있어요. 해변 쉼터, 광장, 체육 시설, 도서관도 지을 수 있어요. 시간은 자동으로 흐르고 세금과 유지비도 매달 정산됩니다.']];let guideIndex=0;
