function setupUI(){renderTools();showGuide();el('guideNext').onclick=()=>{guideIndex++;if(guideIndex>=guideSteps.length){el('guide').classList.add('done');localStorage.setItem('geoje-guide-v1','done')}else showGuide()};el('guideSkip').onclick=()=>{el('guide').classList.add('done');localStorage.setItem('geoje-guide-v1','done')};if(localStorage.getItem('geoje-guide-v1')==='done')el('guide').classList.add('done');el('pause').onclick=()=>setSpeed(speed?0:1);document.querySelectorAll('.speed').forEach(b=>b.onclick=()=>setSpeed(Number(b.dataset.speed)));el('zoomIn').onclick=()=>{camera.position.sub(controls.target).multiplyScalar(.86);controls.update()};el('zoomOut').onclick=()=>{camera.position.sub(controls.target).multiplyScalar(1.16);controls.update()};el('resetCamera').onclick=()=>{camera.position.set(0,32,34);controls.target.set(-.2,.6,.4);controls.update()};el('sound').onclick=()=>{sound=!sound;el('sound').textContent=sound?'♪':'♫';beep(540)};[['res','Res'],['com','Com'],['ind','Ind']].forEach(a=>el('tax'+a[1]).oninput=e=>{state.tax[a[0]]=Number(e.target.value);renderUI()});renderer.domElement.addEventListener('pointerdown',onDown);renderer.domElement.addEventListener('pointerup',onUp);renderer.domElement.addEventListener('pointermove',e=>{let p=cellUnderPointer(e);if(p&&(p.x!==selected?.x||p.y!==selected?.y)){/* hover is kept lightweight */}});window.addEventListener('resize',resize);setSpeed(1)}
